-- Phase 22: deterministic organisation-scoped tasks, cases and operational work.
create table public.work_sla_policies(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.organisations(id) on delete cascade,name text not null,description text,category text,priority text check(priority is null or priority in('low','normal','high','critical')),first_response_minutes integer check(first_response_minutes is null or first_response_minutes>0),resolution_minutes integer check(resolution_minutes is null or resolution_minutes>0),warning_threshold_percent integer not null default 80 check(warning_threshold_percent between 1 and 100),enabled boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(id,organisation_id));
create table public.work_templates(id uuid primary key default gen_random_uuid(),organisation_id uuid references public.organisations(id) on delete cascade,template_type text not null check(template_type in('task','case','case_with_tasks')),name text not null,description text not null default '',category text,default_priority text not null default 'normal' check(default_priority in('low','normal','high','critical')),default_owner_role text,configuration_json jsonb not null default '{}',enabled boolean not null default true,version integer not null default 1 check(version>0),created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(id,organisation_id));
create table public.work_recurrence_rules(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.organisations(id) on delete cascade,template_id uuid,task_id uuid,schedule_type text not null check(schedule_type in('interval','daily','weekly')),schedule_json jsonb not null,next_due_at timestamptz not null,last_generated_at timestamptz,enabled boolean not null default true,created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(id,organisation_id));
create table public.work_cases(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.organisations(id) on delete cascade,case_number text not null,title text not null check(char_length(title) between 1 and 200),summary text,description text,category text not null default 'operational' check(category in('integration','workflow','deployment','data_quality','financial','security','organisation','provider','operational','custom')),status text not null default 'open' check(status in('open','investigating','waiting','resolved','closed','cancelled')),priority text not null default 'normal' check(priority in('low','normal','high','critical')),owner_user_id uuid references auth.users(id),assigned_user_id uuid references auth.users(id),source_type text not null default 'manual',source_id text,source_fingerprint text,opened_at timestamptz not null default now(),first_response_at timestamptz,resolved_at timestamptz,closed_at timestamptz,resolution_summary text,root_cause text,sla_policy_id uuid,metadata_json jsonb not null default '{}',created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(sla_policy_id,organisation_id) references public.work_sla_policies(id,organisation_id),unique(id,organisation_id),unique(organisation_id,case_number));
create table public.work_tasks(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.organisations(id) on delete cascade,case_id uuid,parent_task_id uuid,title text not null check(char_length(title) between 1 and 200),description text,status text not null default 'open' check(status in('backlog','open','in_progress','blocked','waiting','completed','cancelled')),priority text not null default 'normal' check(priority in('low','normal','high','critical')),source_type text not null default 'manual',source_id text,source_fingerprint text,owner_user_id uuid references auth.users(id),assigned_user_id uuid references auth.users(id),assigned_role text,created_by uuid references auth.users(id),due_at timestamptz,started_at timestamptz,completed_at timestamptz,cancelled_at timestamptz,blocked_reason text,waiting_reason text,completion_summary text,estimated_minutes integer check(estimated_minutes is null or estimated_minutes>=0),actual_minutes integer check(actual_minutes is null or actual_minutes>=0),sla_policy_id uuid,recurrence_rule_id uuid,template_id uuid,metadata_json jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(case_id,organisation_id) references public.work_cases(id,organisation_id),foreign key(parent_task_id,organisation_id) references public.work_tasks(id,organisation_id),foreign key(sla_policy_id,organisation_id) references public.work_sla_policies(id,organisation_id),foreign key(recurrence_rule_id,organisation_id) references public.work_recurrence_rules(id,organisation_id),unique(id,organisation_id),check(parent_task_id is null or parent_task_id<>id));
alter table public.work_recurrence_rules add constraint work_recurrence_template_fk foreign key(template_id,organisation_id) references public.work_templates(id,organisation_id),add constraint work_recurrence_task_fk foreign key(task_id,organisation_id) references public.work_tasks(id,organisation_id);
create unique index work_tasks_generated_fingerprint_uidx on public.work_tasks(organisation_id,source_fingerprint) where source_fingerprint is not null;
create unique index work_cases_generated_fingerprint_uidx on public.work_cases(organisation_id,source_fingerprint) where source_fingerprint is not null;
create table public.work_checklist_items(id uuid primary key default gen_random_uuid(),organisation_id uuid not null,task_id uuid not null,label text not null check(char_length(label) between 1 and 300),description text,position integer not null default 0 check(position>=0),required boolean not null default false,completed boolean not null default false,completed_by uuid references auth.users(id),completed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(task_id,organisation_id) references public.work_tasks(id,organisation_id) on delete cascade,unique(id,organisation_id));
create table public.work_dependencies(id uuid primary key default gen_random_uuid(),organisation_id uuid not null,task_id uuid not null,depends_on_task_id uuid not null,dependency_type text not null check(dependency_type in('blocks','requires','related')),created_by uuid references auth.users(id),created_at timestamptz not null default now(),foreign key(task_id,organisation_id) references public.work_tasks(id,organisation_id) on delete cascade,foreign key(depends_on_task_id,organisation_id) references public.work_tasks(id,organisation_id) on delete cascade,check(task_id<>depends_on_task_id),unique(task_id,depends_on_task_id,dependency_type));
create table public.work_assignments(id uuid primary key default gen_random_uuid(),organisation_id uuid not null,work_type text not null check(work_type in('task','case')),task_id uuid,case_id uuid,assigned_user_id uuid references auth.users(id),assigned_role text,assigned_by uuid references auth.users(id),assigned_at timestamptz not null default now(),unassigned_at timestamptz,reason text,created_at timestamptz not null default now(),foreign key(task_id,organisation_id) references public.work_tasks(id,organisation_id) on delete cascade,foreign key(case_id,organisation_id) references public.work_cases(id,organisation_id) on delete cascade,check((work_type='task' and task_id is not null and case_id is null)or(work_type='case' and case_id is not null and task_id is null)));
create table public.work_watchers(id uuid primary key default gen_random_uuid(),organisation_id uuid not null,work_type text not null check(work_type in('task','case')),task_id uuid,case_id uuid,user_id uuid not null references auth.users(id),added_by uuid references auth.users(id),created_at timestamptz not null default now(),foreign key(task_id,organisation_id) references public.work_tasks(id,organisation_id) on delete cascade,foreign key(case_id,organisation_id) references public.work_cases(id,organisation_id) on delete cascade,check((work_type='task' and task_id is not null and case_id is null)or(work_type='case' and case_id is not null and task_id is null)));
create unique index work_watchers_task_uidx on public.work_watchers(task_id,user_id) where task_id is not null;
create unique index work_watchers_case_uidx on public.work_watchers(case_id,user_id) where case_id is not null;
create table public.work_comments(id uuid primary key default gen_random_uuid(),organisation_id uuid not null,work_type text not null check(work_type in('task','case')),task_id uuid,case_id uuid,author_user_id uuid not null references auth.users(id),comment_type text not null check(comment_type in('comment','internal_note','status_note','resolution_note')),body text not null check(char_length(body) between 1 and 5000),edited_at timestamptz,deleted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(task_id,organisation_id) references public.work_tasks(id,organisation_id) on delete cascade,foreign key(case_id,organisation_id) references public.work_cases(id,organisation_id) on delete cascade,check((work_type='task' and task_id is not null and case_id is null)or(work_type='case' and case_id is not null and task_id is null)));
create table public.work_evidence(id uuid primary key default gen_random_uuid(),organisation_id uuid not null,work_type text not null check(work_type in('task','case')),task_id uuid,case_id uuid,evidence_type text not null,source_type text not null,source_id text not null,label text not null,description text,observed_value_json jsonb,expected_value_json jsonb,occurred_at timestamptz,created_by uuid references auth.users(id),created_at timestamptz not null default now(),foreign key(task_id,organisation_id) references public.work_tasks(id,organisation_id) on delete cascade,foreign key(case_id,organisation_id) references public.work_cases(id,organisation_id) on delete cascade,check((work_type='task' and task_id is not null and case_id is null)or(work_type='case' and case_id is not null and task_id is null)),unique(organisation_id,work_type,task_id,case_id,evidence_type,source_type,source_id));
create table public.work_links(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.organisations(id) on delete cascade,from_type text not null,from_id uuid not null,to_type text not null,to_id uuid not null,relationship_type text not null check(relationship_type in('related_to','caused_by','blocks','resolves','generated_from','follow_up_to','duplicates')),created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(organisation_id,from_type,from_id,to_type,to_id,relationship_type));
create table public.work_revisions(id uuid primary key default gen_random_uuid(),organisation_id uuid not null,work_type text not null check(work_type in('task','case')),task_id uuid,case_id uuid,revision_number integer not null check(revision_number>0),change_type text not null,previous_status text,new_status text,previous_priority text,new_priority text,actor_type text not null check(actor_type in('user','system','service')),actor_user_id uuid references auth.users(id),reason text,snapshot_json jsonb not null default '{}',created_at timestamptz not null default now(),foreign key(task_id,organisation_id) references public.work_tasks(id,organisation_id) on delete cascade,foreign key(case_id,organisation_id) references public.work_cases(id,organisation_id) on delete cascade,check((work_type='task' and task_id is not null and case_id is null)or(work_type='case' and case_id is not null and task_id is null)),unique(task_id,revision_number),unique(case_id,revision_number));
create table public.work_saved_views(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.organisations(id) on delete cascade,user_id uuid references auth.users(id),name text not null,description text,view_type text not null check(view_type in('task','case','unified')),filters_json jsonb not null default '[]',sort_json jsonb not null default '[]',columns_json jsonb not null default '[]',is_default boolean not null default false,is_shared boolean not null default false,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.work_runs(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.organisations(id) on delete cascade,run_type text not null,status text not null check(status in('started','completed','failed')),items_evaluated integer not null default 0,tasks_created integer not null default 0,cases_created integer not null default 0,items_updated integer not null default 0,items_escalated integer not null default 0,items_skipped integer not null default 0,started_at timestamptz not null default now(),finished_at timestamptz,error_message text,metadata_json jsonb not null default '{}',created_at timestamptz not null default now());
create table public.work_attachments(id uuid primary key default gen_random_uuid(),organisation_id uuid not null,work_type text not null check(work_type in('task','case')),task_id uuid,case_id uuid,filename text not null,content_type text not null,size_bytes bigint not null check(size_bytes between 0 and 100000000),storage_reference text not null,uploaded_by uuid not null references auth.users(id),uploaded_at timestamptz not null default now(),foreign key(task_id,organisation_id) references public.work_tasks(id,organisation_id) on delete cascade,foreign key(case_id,organisation_id) references public.work_cases(id,organisation_id) on delete cascade,check((work_type='task' and task_id is not null and case_id is null)or(work_type='case' and case_id is not null and task_id is null)));
create index work_tasks_inbox_idx on public.work_tasks(organisation_id,status,priority,due_at,created_at);
create index work_tasks_assignment_idx on public.work_tasks(organisation_id,assigned_user_id,status);
create index work_tasks_case_idx on public.work_tasks(organisation_id,case_id,status);
create index work_cases_inbox_idx on public.work_cases(organisation_id,status,priority,opened_at);
create index work_cases_assignment_idx on public.work_cases(organisation_id,assigned_user_id,status);
create index work_checklist_task_idx on public.work_checklist_items(organisation_id,task_id,position);
create index work_dependencies_task_idx on public.work_dependencies(organisation_id,task_id,depends_on_task_id);
create index work_assignments_lookup_idx on public.work_assignments(organisation_id,work_type,assigned_user_id,assigned_at desc);
create index work_comments_lookup_idx on public.work_comments(organisation_id,work_type,task_id,case_id,created_at desc);
create index work_evidence_lookup_idx on public.work_evidence(organisation_id,work_type,task_id,case_id,created_at desc);
create index work_links_lookup_idx on public.work_links(organisation_id,from_type,from_id);
create index work_revisions_lookup_idx on public.work_revisions(organisation_id,work_type,task_id,case_id,revision_number desc);
create index work_recurrence_due_idx on public.work_recurrence_rules(organisation_id,enabled,next_due_at);
create index work_runs_lookup_idx on public.work_runs(organisation_id,run_type,created_at desc);
create or replace function public.next_work_case_number(target_organisation_id uuid) returns text language plpgsql security definer set search_path=public as $$declare n bigint;begin perform pg_advisory_xact_lock(hashtextextended(target_organisation_id::text,22));select coalesce(max(substring(case_number from 6)::bigint),0)+1 into n from public.work_cases where organisation_id=target_organisation_id;return 'CASE-'||lpad(n::text,6,'0');end$$;
revoke all on function public.next_work_case_number(uuid) from public,anon,authenticated;
do $$declare t text;begin foreach t in array array['work_sla_policies','work_templates','work_recurrence_rules','work_cases','work_tasks','work_checklist_items','work_dependencies','work_assignments','work_watchers','work_comments','work_evidence','work_links','work_revisions','work_saved_views','work_runs','work_attachments']loop execute format('alter table public.%I enable row level security',t);end loop;end$$;
do $$declare t text;begin foreach t in array array['work_sla_policies','work_recurrence_rules','work_cases','work_tasks','work_checklist_items','work_dependencies','work_assignments','work_watchers','work_comments','work_evidence','work_links','work_revisions','work_saved_views','work_runs','work_attachments']loop execute format('create policy "Members read %1$s" on public.%1$I for select to authenticated using(public.is_organisation_member(organisation_id))',t);end loop;end$$;
create policy "Members read work templates" on public.work_templates for select to authenticated using(organisation_id is null or public.is_organisation_member(organisation_id));
create policy "Operators create tasks" on public.work_tasks for insert to authenticated with check(created_by=auth.uid() and public.has_organisation_role(organisation_id,array['owner','admin','manager','member']));
create policy "Managers update tasks" on public.work_tasks for update to authenticated using(public.has_organisation_role(organisation_id,array['owner','admin','manager']) or assigned_user_id=auth.uid()) with check(public.has_organisation_role(organisation_id,array['owner','admin','manager']) or assigned_user_id=auth.uid());
create policy "Operators create cases" on public.work_cases for insert to authenticated with check(created_by=auth.uid() and public.has_organisation_role(organisation_id,array['owner','admin','manager']));
create policy "Managers update cases" on public.work_cases for update to authenticated using(public.has_organisation_role(organisation_id,array['owner','admin','manager']) or assigned_user_id=auth.uid()) with check(public.has_organisation_role(organisation_id,array['owner','admin','manager']) or assigned_user_id=auth.uid());
create policy "Members comment" on public.work_comments for insert to authenticated with check(author_user_id=auth.uid() and public.has_organisation_role(organisation_id,array['owner','admin','manager','member']) and(comment_type<>'internal_note' or public.has_organisation_role(organisation_id,array['owner','admin','manager'])));
create policy "Members watch" on public.work_watchers for insert to authenticated with check(user_id=auth.uid() and public.is_organisation_member(organisation_id));
create policy "Members unwatch" on public.work_watchers for delete to authenticated using(user_id=auth.uid());
create policy "Managers manage checklists" on public.work_checklist_items for all to authenticated using(public.has_organisation_role(organisation_id,array['owner','admin','manager']) or exists(select 1 from public.work_tasks t where t.id=task_id and t.organisation_id=organisation_id and t.assigned_user_id=auth.uid())) with check(public.has_organisation_role(organisation_id,array['owner','admin','manager']) or exists(select 1 from public.work_tasks t where t.id=task_id and t.organisation_id=organisation_id and t.assigned_user_id=auth.uid()));
create policy "Admins manage work settings" on public.work_sla_policies for all to authenticated using(public.has_organisation_role(organisation_id,array['owner','admin'])) with check(public.has_organisation_role(organisation_id,array['owner','admin']));
create policy "Admins manage work templates" on public.work_templates for all to authenticated using(organisation_id is not null and public.has_organisation_role(organisation_id,array['owner','admin'])) with check(organisation_id is not null and public.has_organisation_role(organisation_id,array['owner','admin']));
create policy "Members manage own views" on public.work_saved_views for all to authenticated using(created_by=auth.uid() or(user_id is null and public.has_organisation_role(organisation_id,array['owner','admin','manager']))) with check(created_by=auth.uid() and public.is_organisation_member(organisation_id));
revoke insert,update,delete on public.work_revisions,public.work_evidence,public.work_runs from authenticated;
